From ad66d3c489609b3ebd65a20526255507ddcf7f20 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:09:10 +0100
Subject: [PATCH] wallpapers/potd: always download the UHD Bing image on
 landscape screens

Bing's 1920x1080 images are so heavily compressed that they look blurry
and blocky even on a 1080p screen, while its UHD image downscaled to the
same size looks clean, so use the UHD image for every landscape screen.

BUG: 487274
---
 wallpapers/potd/package/contents/ui/config.qml | 6 ++----
 wallpapers/potd/package/contents/ui/main.qml   | 6 ++----
 2 files changed, 4 insertions(+), 8 deletions(-)

diff --git a/wallpapers/potd/package/contents/ui/config.qml b/wallpapers/potd/package/contents/ui/config.qml
index 0975d106e..a310048fd 100644
--- a/wallpapers/potd/package/contents/ui/config.qml
+++ b/wallpapers/potd/package/contents/ui/config.qml
@@ -38,11 +38,9 @@ Kirigami.FormLayout {
                 if (h > w) {
                     // Portrait orientation
                     return [1080, 1920];
-                } else if (w > 1920 || h > 1080) {
-                    // UHD resolution
-                    return [3840, 2160];
                 } else {
-                    return [1920, 1080];
+                    // Always use UHD: the smaller images are heavily compressed
+                    return [3840, 2160];
                 }
             }
             return [];
diff --git a/wallpapers/potd/package/contents/ui/main.qml b/wallpapers/potd/package/contents/ui/main.qml
index b179ce7e6..0a25f47be 100644
--- a/wallpapers/potd/package/contents/ui/main.qml
+++ b/wallpapers/potd/package/contents/ui/main.qml
@@ -89,11 +89,9 @@ WallpaperItem {
                     if (h > w) {
                         // Portrait orientation
                         return [1080, 1920];
-                    } else if (w > 1920 || h > 1080) {
-                        // UHD resolution
-                        return [3840, 2160];
                     } else {
-                        return [1920, 1080];
+                        // Always use UHD: the smaller images are heavily compressed
+                        return [3840, 2160];
                     }
                 }
                 return [];
-- 
